"""Explicit read-only attribution worksheet, not a production grouping algorithm."""
import hashlib,json
from pathlib import Path
from decimal import Decimal
cp=Path('real-review/input/comparison-data.json');qp=Path('whole-membership-review/input/source-query.json');cr=cp.read_bytes();qr=qp.read_bytes();cs=hashlib.sha256(cr).hexdigest();qs=hashlib.sha256(qr).hexdigest();assert cs=='184bdef0b687ec0ab7bfcaaac2157ff7916fbc1000ef312d81b5efc0c2e73e15';assert qs=='4a43a8c0f03bbffacb86306f064b7c807a7a83bdaf7e737bc76cd654a2c1dbb0'
p=json.loads(cr);q=json.loads(qr);by={x['id']:x for x in p['core']['pivots']}
def detail(tid):
 v=by[tid];b=p['bars'][v['occurred_index']];assert b['date']==v['occurred_at'];assert Decimal(b['high' if v['kind']=='HIGH' else 'low'])==Decimal(v['price']);return {'original_pivot':v,'original_bar':b}
querypath=q['paths'][0];route=[by[x] for x in querypath['turn_ids']];seq3=sorted([x for x in by.values() if x['scale']=='0.03' and x['segment']==0],key=lambda x:x['occurred_index']);a=next(i for i,x in enumerate(seq3) if x['id']==route[0]['id']);assert seq3[a:a+len(route)]==route and len(route)==9
boxes={f'B{n}':p['core']['boxes'][n-1] for n in [16,17,18,44,77,80]}
A=route[0];assert A['occurred_at']=='2023-06-05' and A['price']=='39.25'
assert all(A['id'] in boxes[f'B{n}']['source_turn_ids'] and boxes[f'B{n}']['start']<'2023-06-01' for n in [16,17,18])
b77=boxes['B77'];seq6=sorted([x for x in by.values() if x['scale']=='0.06' and x['segment']==0],key=lambda x:x['occurred_index']);last=b77['source_turn_ids'][-1];k=next(i for i,x in enumerate(seq6) if x['id']==last);right=seq6[k:k+5]
assert [(x['occurred_at'],x['kind'],x['price'],x['confirmed_at']) for x in right]==[('2025-03-12','HIGH','35.45','2025-03-24'),('2025-04-08','LOW','28.45','2025-04-10'),('2025-04-10','HIGH','31.20','2025-04-18'),('2025-04-22','LOW','28.50','2025-05-05'),('2025-05-13','HIGH','31.40','2025-05-27')]
assert [x['id'] for x in right[1:]]==boxes['B80']['source_turn_ids'];assert b77['source_end']=='2025-03-12' and b77['confirmed_at']=='2025-03-24'
assert [(by[x]['occurred_at'],by[x]['price']) for x in boxes['B44']['source_turn_ids']]==[(by[x]['occurred_at'],by[x]['price']) for x in boxes['B80']['source_turn_ids']]
assert boxes['B44']['confirmed_at']=='2025-05-14' and boxes['B80']['confirmed_at']=='2025-05-27'
# Correspondences are explicit evidence rows, never unioned into a mixed-scale path.
correspondences=[]
for d in ['2023-10-24','2023-11-28']:
 x=next(x for x in route if x['occurred_at']==d);y=next(by[i] for i in b77['source_turn_ids'] if by[i]['occurred_at']==d)
 assert x['kind']==y['kind'] and x['price']==y['price'] and x['id']!=y['id'] and x['scale']!=y['scale']
 correspondences.append({'route_3pct_pivot':x,'B77_6pct_pivot':y,'coordinate_equal':True,'ids_distinct':True,'formal_shared_roles':None,'formal_merge':None})
roles=[{'part':'earlier_high_source','evidence':'A原39.25及B16/B17/B18引用','research_role':'較早高位候選來源','formal_membership':None},{'part':'downward_link_with_rebounds','evidence':'原3%同段完整9點路徑，含末段反彈','research_role':'較早高位至後段區的過程證據','formal_membership':None},{'part':'later_repeated_region','evidence':'B77原6%十來源與完整廣角價量','research_role':'後段反覆區候選描述，非整個人工整體','formal_membership':None},{'part':'april_transition_context','evidence':'原6%3/12→4/8→4/10→4/22，後續5/13另列','research_role':'右端轉弱及低位反彈的待歸屬觀察','formal_membership':None}]
e={'schema':'m1-explicit-attribution-worksheet/1','qualification':'ASSISTANT_RESEARCH_NOT_FORMAL_GROUPING_OR_NEW_QUERY','source_comparison_sha256':cs,'source_query_sha256':qs,'original_core_result_id':p['core']['result_id'],'manual_month_background_unchanged':p['manual_case_audit']['larger_manual_band'],'roles':roles,'A':detail(A['id']),'original_boxes':{name:{k:b[k] for k in ['id','scale','segment','start','source_end','confirmed_at','source_turn_ids','formal_region_membership','formal_price_bounds']} for name,b in boxes.items()},'original_3pct_query_path':querypath,'original_3pct_path_records':[detail(x['id']) for x in route],'B77_original_sources':[detail(x) for x in b77['source_turn_ids']],'cross_scale_correspondences_not_joined':correspondences,'right_context_6pct_contiguous':[detail(x['id']) for x in right],'right_context_scope':'first 4 pivots for Mar-to-Apr observation; fifth May13 is explicit later context, not a guessed formal end','april_22_occurrence_vs_confirmation':{'occurred_at':'2025-04-22','confirmed_at':'2025-05-05','occurred_within_display_month':True,'confirmed_within_display_month':False,'formal_membership':None},'primary_pressure_id':None,'historical_selection_time':None,'historical_signal_eligible':False,'formal_structure_membership':None,'formal_merge':None,'formal_representative':None,'direct_successor_id':None}
out=Path('attribution-map-review');(out/'evidence.json').write_text(json.dumps(e,ensure_ascii=False,indent=2)+'\n')
assert hashlib.sha256(cp.read_bytes()).hexdigest()==cs and hashlib.sha256(qp.read_bytes()).hexdigest()==qs
(out/'verification.json').write_text(json.dumps({'source_hashes_unchanged':True,'original_A_referenced_by_three_left_crossing_boxes':True,'original_query_9_pivots_exact_contiguous_same_scale_segment':True,'B77_10_sources_original_OHLC_confirmations_checked':True,'cross_scale_two_correspondences_ids_kept_separate':True,'right_6pct_5_pivots_exact_contiguous_original_sequence':True,'B80_four_sources_are_right_context_suffix':True,'B44_B80_coordinates_equal_ids_distinct_original_confirmations_kept':True,'april_occurrence_and_may_confirmation_not_conflated':True,'no_formal_membership_assignment':True,'new_query_adapter_CLI_core_MACD_reaction':'NOT_RUN','new_image_zoom_UI':'NOT_CREATED_USER_SAID_THIS_TIME_OK','browser':'NOT_RUN','product_tests':'NOT_RUN','Android':'NOT_TESTED_NEW_BUILD'},ensure_ascii=False,indent=2)+'\n');print(json.dumps({'A':A['occurred_at'],'left_boxes':3,'query_path_records':len(route),'B77_sources':len(b77['source_turn_ids']),'right_path_records':len(right),'same_coordinate_cross_scale_rows':len(correspondences)},ensure_ascii=False))
